#include <stdio.h>

static int add(int a, int b) { return a + b; }
static int sub(int a, int b) { return a - b; }
static int mul(int a, int b) { return a * b; }

typedef int (*binop)(int, int);

static int apply(binop f, int a, int b) {   /* callback parameter */
    return f ? f(a, b) : 0;
}

int main(void) {
    int (*fp)(int, int) = add;              /* same as &add */
    printf("%d\n", fp(6, 3));               /* 9 */
    fp = sub;
    printf("%d\n", (*fp)(6, 3));            /* 3 */

    binop table[] = { add, sub, mul };      /* dispatch table */
    const char *names[] = { "add", "sub", "mul" };
    for (int i = 0; i < 3; i++)
        printf("%s: %d\n", names[i], apply(table[i], 6, 3));
    return 0;
}

int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}
int v[] = {5, 2, 9, 1};
qsort(v, 4, sizeof v[0], cmp_int);

